begin;
set local role service_role;
do $test$
declare actor uuid;ordinary uuid;member public.social_admins;person uuid:=gen_random_uuid();person2 uuid:=gen_random_uuid();team uuid:=gen_random_uuid();r jsonb;d jsonb;ctx jsonb;record jsonb;payload jsonb;snapshot jsonb;cid uuid;before_count int;
begin
 select user_id into actor from public.social_admins where role='admin' and is_active and not is_blocked limit 1;
 select * into member from public.social_admins where role<>'admin' and is_active and not is_blocked and not 'trainer_contracts'=any(access_areas) limit 1;ordinary:=member.user_id;
 if actor is null or ordinary is null then raise exception 'Test actors missing';end if;
 update public.social_admins set extra_access_areas=array_append(extra_access_areas,'trainer_management') where user_id=ordinary;
 insert into public.social_people(id,slug,display_name,roles,active,birth_date) values(person,'privacy-test-'||person,'Private Coach','{}',true,'1990-01-01'),(person2,'privacy-test-'||person2,'Other Coach','{}',true,null);
 insert into private.trainer_profiles(person_id,first_name,last_name,email,phone,street,notes) values(person,'Private','Coach','club@example.test','+49 111','Existing street','Existing note'),(person2,'Other','Coach','','','','');
 insert into public.social_teams(id,slug,name,competition,family_key) select team,'u15-privacy-test-'||team,'C-Jugend Privacy Test',t.competition,t.family_key from public.social_teams t where t.slug ~ '^u15' limit 1;
 insert into public.social_team_people(team_id,person_id,role,staff_slot) values(team,person,'Trainer','trainer');
 perform public.employee_management_request(actor,jsonb_build_object('action','save_assignment','groupKey','board','roleLabel','Privacy test','personId',person,'version',0));
 if public.trainer_personal_request(ordinary,jsonb_build_object('action','get','personId',person))->>'status'<>'403' then raise exception 'Ordinary staff read protected data';end if;
 record:=jsonb_build_object('personId',person,'expectedFirstName','Private','expectedLastName','Coach','profileVersion',1,'messageId','1111111111111111','sourceDate','2026-11-01T12:00:00Z','details',jsonb_build_object('email','private@example.test','mobile','+49 222','street','Different street','birthDate','1991-01-01','bank',jsonb_build_object('holder','Guardian Coach','iban','DE89370400440532013000','name','Example Bank','bic','COBADEFFXXX')));
 if private.import_trainer_personal_data(ordinary,jsonb_build_array(record))->>'status'<>'403' then raise exception 'Ordinary staff imported protected data';end if;
 r:=private.import_trainer_personal_data(actor,jsonb_build_array(record));if r->>'ok'<>'true' or not (r#>'{results,0,conflictFields}') ?& array['birthDate','street'] then raise exception 'Import fill/conflict failed: %',r;end if;
 d:=public.trainer_personal_request(actor,jsonb_build_object('action','get','personId',person));
 if d#>>'{details,email}'<>'private@example.test' or d#>>'{details,bank,holder}'<>'Guardian Coach' or d#>>'{details,birthDate}'<>'1990-01-01' or d#>>'{details,street}'<>'Existing street' then raise exception 'Import overwrite or placeholder bank holder';end if;
 if not exists(select 1 from private.trainer_profiles where person_id=person and email='club@example.test' and phone='+49 111' and not public_phone) then raise exception 'Private import changed operational contacts';end if;
 r:=private.import_trainer_personal_data(actor,jsonb_build_array(record));if r#>>'{results,0,skipped}'<>'true' then raise exception 'Import not idempotent';end if;
 for r in select public.trainer_management_request(who,jsonb_build_object('action','list')) from unnest(array[actor,ordinary]) who loop
  if r ? 'error' or exists(select 1 from jsonb_array_elements(r->'people') p where p ?| array['email','phone','mobile','birth_date','street','postcode','city','notes','bank']) then raise exception 'Directory leaked private data';end if;
 end loop;
 r:=public.employee_management_request(ordinary,'{"action":"list"}');if not exists(select 1 from jsonb_array_elements(r->'people') p where p->>'id'=person::text and p->>'contactProtected'='true' and not p ?| array['email','phone','mobile']) then raise exception 'Employee contact route leaked trainer data';end if;
 r:=public.employee_management_request(actor,jsonb_build_object('action','save_contact','personId',person,'version',1,'email','changed@example.test'));if r->>'status'<>'403' then raise exception 'Alternate trainer contact write accepted';end if;
 update public.social_admins set extra_access_areas=array_append(extra_access_areas,'trainer_contracts') where user_id=ordinary;
 if public.trainer_personal_request(ordinary,jsonb_build_object('action','get','personId',person)) ? 'error' then raise exception 'Explicit contract grant ineffective';end if;
 ctx:=public.trainer_contract_request(actor,'{"action":"source","season":"2098/2099"}');
 if not exists(select 1 from jsonb_array_elements(ctx->'people') p where p->>'id'=person::text and p#>>'{personalBank,holder}'='Guardian Coach' and p->>'personalVersion'='1' and p->>'email'='private@example.test') then raise exception 'Contract sources miss protected onboarding data';end if;
 snapshot:=jsonb_build_object('templateVersion','2026-11-03.1','season','2098/2099','personId',person,'teamId',team,'slot','trainer','name','Private Coach','teamName','Privacy Test','monthlyCents',1000,'paidMonths','[7,9,10,11,1,2,3,4,5,6]'::jsonb,'financialConfirmed',true,'source',jsonb_build_object('personVersion',1,'personalVersion',1,'planVersion',0,'teamVersion',(select trainer_version from public.social_teams where id=team),'birthDate','1990-01-01','teamName','C-Jugend Privacy Test'));
 r:=public.trainer_contract_request(actor,jsonb_build_object('action','create','season','2098/2099','personId',person,'teamId',team,'slot','trainer','snapshot',snapshot));cid:=(r->>'id')::uuid;if cid is null then raise exception 'Draft fixture failed: %',r;end if;
 payload:=jsonb_build_object('action','save','personId',person,'version',1,'profileVersion',1,'details',jsonb_set(d->'details','{bank,name}','"Updated bank"'));
 r:=public.trainer_personal_request(actor,payload);if r->>'version'<>'2' then raise exception 'Protected save failed: %',r;end if;
 r:=public.trainer_personal_request(actor,payload);if r->>'status'<>'409' then raise exception 'Lost private update accepted';end if;
 r:=public.trainer_contract_request(actor,jsonb_build_object('action','issue','id',cid,'version',1,'path',cid||'/issued/test.pdf','hash',repeat('a',64)));if r->>'status'<>'409' then raise exception 'Stale private bank source issued';end if;
 payload:=payload||jsonb_build_object('version',2,'publishPhone',true);r:=public.trainer_personal_request(actor,payload);if r->>'ok'<>'true' or not exists(select 1 from private.trainer_profiles where person_id=person and phone='+49 111' and mobile='' and public_phone and version=2) then raise exception 'Explicit publication copied private phone';end if;
 r:=public.trainer_personal_request(actor,payload||jsonb_build_object('version',3));if r->>'status'<>'409' then raise exception 'Stale profile revision accepted';end if;
 r:=public.trainer_personal_request(actor,payload||jsonb_build_object('version',3,'profileVersion',2,'details',jsonb_build_object('bank',jsonb_build_object('iban','DE00370400440532013000'))));if r->>'status'<>'400' then raise exception 'Invalid IBAN accepted';end if;
 select count(*) into before_count from private.trainer_personal_imports;
 r:=private.import_trainer_personal_data(actor,jsonb_build_array(record||jsonb_build_object('profileVersion',2,'messageId','2222222222222222'),record||jsonb_build_object('profileVersion',2,'messageId','3333333333333333','details',jsonb_build_object('birthDate','2026-02-30'))));
 if r->>'status'<>'400' or (select count(*) from private.trainer_personal_imports)<>before_count then raise exception 'Batch validation partially wrote imports';end if;
 record:=jsonb_build_object('personId',person2,'expectedFirstName','Other','expectedLastName','Coach','profileVersion',1,'messageId','4444444444444444','sourceDate','2026-11-01T12:00:00Z','details',jsonb_build_object('bank',jsonb_build_object('holder','Manual guardian','name','Manual bank','iban','')),'ignoredFields',jsonb_build_array('bank.iban'));
 r:=private.import_trainer_personal_data(actor,jsonb_build_array(record));d:=public.trainer_personal_request(actor,jsonb_build_object('action','get','personId',person2));if d#>>'{details,bank,holder}'<>'Manual guardian' then raise exception 'Useful bank details without a valid IBAN were lost';end if;
 record:=record||jsonb_build_object('messageId','5555555555555555','details',jsonb_build_object('bank',jsonb_build_object('holder','Different guardian','name','Other bank','iban','DE89370400440532013000')));r:=private.import_trainer_personal_data(actor,jsonb_build_array(record));d:=public.trainer_personal_request(actor,jsonb_build_object('action','get','personId',person2));if not (r#>'{results,0,conflictFields}') ? 'bank' or d#>>'{details,bank,holder}'<>'Manual guardian' or coalesce(d#>>'{details,bank,iban}','')<>'' then raise exception 'Import mixed or overwrote an existing partial bank identity';end if;
 update public.social_admins set extra_access_areas=array_remove(extra_access_areas,'trainer_contracts') where user_id=ordinary;
 r:=public.trainer_management_request(ordinary,jsonb_build_object('action','save_person','personId',person,'version',2,'firstName','Private','lastName','Coach','active',true,'websiteName','Private Coach','qualification','Updated qualification','club','BSV Nordstern'));
 if r->>'ok'<>'true' or not exists(select 1 from private.trainer_profiles where person_id=person and email='club@example.test' and phone='+49 111' and street='Existing street' and notes='Existing note') or not exists(select 1 from public.social_people where id=person and birth_date='1990-01-01') then raise exception 'General edit cleared hidden private values: %',r;end if;
 if public.trainer_personal_request(ordinary,jsonb_build_object('action','get','personId',person))->>'status'<>'403' then raise exception 'Revoked contract grant remained effective';end if;
 if has_function_privilege('authenticated','public.trainer_personal_request(uuid,jsonb)','execute') or has_function_privilege('anon','private.import_trainer_personal_data(uuid,jsonb)','execute') or has_table_privilege('authenticated','private.trainer_personal_data','select') or has_table_privilege('anon','private.trainer_personal_imports','select') then raise exception 'Protected data exposed to database clients';end if;
 if exists(select 1 from pg_class where oid in ('private.trainer_personal_data'::regclass,'private.trainer_personal_imports'::regclass) and not relrowsecurity) then raise exception 'Private RLS missing';end if;
end $test$;
rollback;
